import { parseStock } from './input/csv.js';
import { normalizeStock } from './domain/stock.js';
import { wireStock } from './output/wire.js';
export function importStock(text) { return wireStock(normalizeStock(parseStock(text))); }
export function parseStock(text) {
  const [sku, available, reserved] = text.trim().split(',');
  return { sku, available: Number(available), reserved: Number(reserved) };
}
import { canonicalSku } from './sku.js';
export function normalizeStock(row) {
  if (![row.available, row.reserved].every(Number.isFinite)) throw new Error('invalid count');
  return { sku: canonicalSku(row.sku), count: Math.max(0, row.available - row.reserved) };
}
export function canonicalSku(value) { return value.trim().toUpperCase(); }
export function wireStock(item) { return { product_code: item.sku, units: item.count, schema: 2 }; }

