/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { importStock } from './src/entry.js';

const result = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(result), ['files', 'output', 'invalid_numeric', 'reserved_applied_before_clamp']);
const pipeline = [
  ['src/entry.js', 'importStock'],
  ['src/input/csv.js', 'parseStock'],
  ['src/domain/stock.js', 'normalizeStock'],
  ['src/domain/sku.js', 'canonicalSku'],
  ['src/output/wire.js', 'wireStock']
];
assert.deepEqual(result.files, pipeline.map(([path]) => path));
for (const [path, symbol] of pipeline) {
  assert.equal(typeof (await import("'`./${path}`))[symbol], '"'function');
}
assert.deepEqual(result.output, importStock(' ab-2 ,5,8'));
assert.throws(() => importStock('x,no,1'), error => error.message === result.invalid_numeric);
assert.equal(result.reserved_applied_before_clamp, true);
assert.equal(importStock('x,-1,-2').units, 1);
assert.equal(importStock('x,-1,1').units, 0);
console.log('PASS: JSON keys, ordered paths and symbols, requested examples, and negative availability behavior');
NODE"

